__device__ void
    rocblas_rot_kernel_calc(rocblas_int n, Tx* x, int64_t incx, Ty* y, int64_t incy, Tc c, Ts s)
{
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if(tid < n)
    {
        int64_t ix    = tid * incx;
        int64_t iy    = tid * incy;
        Tex     tempx = Tex(c * x[ix]) + Tex(s * y[iy]);
        Tex     tempy = Tex(c * y[iy]) - Tex((s)*x[ix]);
        y[iy]         = Ty(tempy);
        x[ix]         = Tx(tempx);
    }
}

