                               stream));
    CUDA_CHECK(cudaMemcpyAsync(B.data(), d_B, sizeof(data_type) * B.size(), cudaMemcpyDeviceToHost,
                               stream));

    CUDA_CHECK(cudaStreamSynchronize(stream));

    /*
     *   A = | 5.0 6.0 7.0 8.0 |
     *   B = | 1.0 2.0 3.0 4.0 |
     */

