struct GPUTimer
{
    GPUTimer() 
    {
        hipEventCreate(&start_);
        hipEventCreate(&stop_);
        hipEventRecord(start_, nullptr);
    }

    ~GPUTimer() 
    {
        hipEventDestroy(start_);
        hipEventDestroy(stop_);
    }

    void start() 
    {
        hipEventRecord(start_, nullptr);
    }

    float seconds() 
    {
        hipEventRecord(stop_, nullptr);
        hipEventSynchronize(stop_);
