template <typename DataType, bool IsUnpack>
__global__ void strided_copy_kernel(const DataType* __restrict__ src,
                                    DataType* __restrict__ dst,
                                    const index_t* tensor_lengths,
                                    const index_t* strided_strides,
                                    int num_dims,
                                    long_index_t total_elements)
{
    const long_index_t tid         = blockIdx.x * blockDim.x + threadIdx.x;
    const long_index_t num_threads = blockDim.x * gridDim.x;

    for(long_index_t linear_idx = tid; linear_idx < total_elements; linear_idx += num_threads)
    {
        // Compute strided index from linear index
        long_index_t remaining   = linear_idx;
        long_index_t strided_idx = 0;

        for(int dim = num_dims - 1; dim >= 0; --dim)
        {
            index_t coord = remaining % tensor_lengths[dim];
            remaining /= tensor_lengths[dim];
            strided_idx += coord * strided_strides[dim];
        }

        // Direction determines which is src and which is dst
        if constexpr(IsUnpack)
        {
            // Unpack: src is contiguous (linear_idx), dst is strided (strided_idx)
            dst[strided_idx] = src[linear_idx];
        }
        else
        {
            // Pack: src is strided (strided_idx), dst is contiguous (linear_idx)
            dst[linear_idx] = src[strided_idx];
        }
    }
}

__host__ __device__ f4x32_t f4_convert_sr(float32_t x, float scale = 1.0f)
{
#if defined(__gfx950__)
    // use HW clock for stochastic input multiply by incremented thread id
    uint32_t rng = __builtin_amdgcn_prng_b32(__builtin_amdgcn_s_memrealtime() *
                                             (get_thread_global_1d_id() + 1));
    union
    {
        __uint128_t bitwise;
        f4x2_t f4x2_array[16];
        f4x32_t f4x32_array;
    } f4_values{0};
    union
    {
        float2_t floatx2_array[16];
        float32_t floatx32_array;
    } float_values{{0}};
    float_values.floatx32_array = x;

    ck::static_for<0, 32 / 2, 1>{}([&](auto idx) {
        f4_values.f4x2_array[idx] = __builtin_amdgcn_cvt_scalef32_sr_pk_fp4_f32(
            f4_values.bitwise, float_values.floatx2_array[idx], rng, scale, 0);
    });

    return f4_values.f4x32_array;
#else
    constexpr int seed = 1254739;
#ifndef CK_CODE_GEN_RTC
    uint32_t rng = prand_generator<float, seed>(reinterpret_cast<uintptr_t>(&x), x[0]);
#else
    uint32_t rng = prand_generator<float, seed>(reinterpret_cast<size_t>(&x), x[0]);
#endif
    union
    {
        __uint128_t bitwise;
        f4x2_t f4x2_array[16];
        f4x32_t f4x32_array;
    } f4_values{0};

    f4_t tmp;

    ck::static_for<0, 32, 1>{}([&](auto idx) {
        tmp = utils::sat_convert_to_type_sr<f4_t>(x[static_cast<int>(idx)] / scale, rng);
        f4_values.bitwise <<= 4;
        f4_values.bitwise |= tmp;
    });

    return f4_values.f4x32_array;
#endif
}

