 */

#include <iostream>
using std::cerr;
using std::endl;

#include "simpleMPI.h"

// Error handling macro
#define CUDA_CHECK(call)                                                     \
    if ((call) != cudaSuccess) {                                             \
        cudaError_t err = cudaGetLastError();                                \
        cerr << "CUDA error calling \"" #call "\", code is " << err << endl; \
        my_abort(err);                                                       \
    }

// Device code
// Very simple GPU Kernel that computes square roots of input numbers
