template <typename IDX, typename E>
__device__ void getitembuildindices(const IDX* __restrict__ index,
                                    IDX* __restrict__ element_index,
                                    E* __restrict__ error,
                                    int32_t index_dim,
                                    int32_t indexCount,
                                    int32_t dim_size,
                                    tensor_view_t<5> index_tv,
                                    int32_t dim_offset,
                                    int32_t dim_info_offset)
{
    const uint64_t gid = threadIdx.x + blockIdx.x * blockDim.x;

    tensor_layout_t<5> ncdhw(index_tv, gid);

    if(ncdhw.layout[0] >= index_tv.size[0])
        return;

    uint64_t idx      = index_tv.get_tensor_view_idx(ncdhw);
    IDX getitem_index = index[idx];

    if(getitem_index >= 0 && getitem_index < dim_size)
    {
        element_index[(gid * indexCount) + dim_offset] = getitem_index;
    }
    else if(getitem_index >= -dim_size && getitem_index < 0)
    {
        element_index[(gid * indexCount) + dim_offset] = getitem_index + dim_size;
    }
    else
    {
        error[dim_offset] = -1;
    }

    if(gid == 0)
    {
        element_index[dim_info_offset + dim_offset] = index_dim;
    }
}

template <index_t AStride = GemmMPerWave, index_t BStride = GemmNPerWave>
    __device__ static MatrixIndex GetBeginOfThreadMatrixC(index_t i)
    {

        const index_t waveId = get_thread_local_1d_id() / WaveSize;

#if CK_WORKAROUND_SWDEV_241664
        const index_t xdlops_i = i / XdlopsGemm.GetOutputLayout().GetNumBlks();
        const index_t j        = i % XdlopsGemm.GetOutputLayout().GetNumBlks();

        const index_t m = xdlops_i / NRepeats;
        const index_t n = xdlops_i % NRepeats;

        const auto thread_mtx_on_blk = XdlopsGemm.GetBeginOfThreadBlk(j);

        const index_t col =
            (waveId % GemmNWaves) * BStride + n * NPerXdlops + thread_mtx_on_blk.col;
        const index_t row =
            (waveId / GemmNWaves) * AStride + m * MPerXdlops + thread_mtx_on_blk.row;
#else
        const auto thread_mtx_on_blk = XdlopsGemm.GetBeginOfThreadBlk(i);

        const index_t col = (waveId % GemmNWaves) * BStride + thread_mtx_on_blk.col;
        const index_t row = (waveId / GemmNWaves) * AStride + thread_mtx_on_blk.row;
#endif

        return MatrixIndex{row, col};
    }

