            string msg("Could not copy direction vectors to device: ");
            msg += hipGetErrorString(cudaResult);
            throw std::runtime_error(msg);
        }
    }
    else if (typeid(Real) == typeid(double)) {
        curandDirectionVectors64_t *rngDirections;
        curandStatus_t curandResult = curandGetDirectionVectors64(&rngDirections, CURAND_DIRECTION_VECTORS_64_JOEKUO6);

        if (curandResult != CURAND_STATUS_SUCCESS) {
            string msg("Could not get direction vectors for quasi-random number "
                       "generator: ");
            msg += curandResult;
            throw std::runtime_error(msg);
        }

        cudaResult =
            hipMemcpy(d_rngDirections, rngDirections, 2 * sizeof(curandDirectionVectors64_t), hipMemcpyHostToDevice);

        if (cudaResult != hipSuccess) {
            string msg("Could not copy direction vectors to device: ");
            msg += hipGetErrorString(cudaResult);
            throw std::runtime_error(msg);
        }
    }
    else {
        string msg("Could not get direction vectors for random number generator of "
                   "specified type");
        throw std::runtime_error(msg);
    }

    // Initialise RNG
    initRNG<<<grid, block, 0, 0>>>(d_rngStates, d_rngDirections, m_numSims);

    // Count the points inside unit quarter-circle
    computeValue<Real><<<grid, block, block.x * sizeof(unsigned int)>>>(d_results, d_rngStates, m_numSims);

    // Copy partial results back
    vector<unsigned int> results(grid.x);
    cudaResult = hipMemcpy(&results[0], d_results, grid.x * sizeof(unsigned int), hipMemcpyDeviceToHost);

    if (cudaResult != hipSuccess) {
        string msg("Could not copy partial results to host: ");
        msg += hipGetErrorString(cudaResult);
        throw std::runtime_error(msg);
    }

    // Complete sum-reduction on host
    Real value = static_cast<Real>(std::accumulate(results.begin(), results.end(), 0));

    // Determine the proportion of points inside the quarter-circle,
    // i.e. the area of the unit quarter-circle
    value /= m_numSims;

    // Value is currently an estimate of the area of a unit quarter-circle, so we
    // can scale to a full circle by multiplying by four. Now since the area of a
    // circle is pi * r^2, and r is one, the value will be an estimate for the
    // value of pi.
    value *= 4;

    // Cleanup
    if (d_rngStates) {
        hipFree(d_rngStates);
        d_rngStates = 0;
    }

    if (d_rngDirections) {
        hipFree(d_rngDirections);
        d_rngDirections = 0;
    }

    if (d_results) {
        hipFree(d_results);
        d_results = 0;
    }

    return value;
}

