        float *volumeData = (float *)malloc(elements * 4 * sizeof(float));
        float *ptr        = volumeData;

        for (size_t i = 0; i < elements; i++) {
            *ptr++ = frand() * 2.0f - 1.0f;
            *ptr++ = frand() * 2.0f - 1.0f;
            *ptr++ = frand() * 2.0f - 1.0f;
            *ptr++ = frand() * 2.0f - 1.0f;
