    out.float_vector = __builtin_amdgcn_cvt_scalef32_pk32_f32_fp6(
        in.f6_vector.template AsType<f6x32_t::data_t>()[Number<0>{}],
        type_convert<float>(NumericLimits<e8m0_bexp_t>::Binary_1()));
