            if (is_upper_tri) {
                __stcg(A + i + (jj+j)*lda, As[i + (jj+j)*ldas]);
            }
        }
    } else {
        for (int k = tid; k < NB*NB; k += NT) {
            unsigned i = k % NB;
            unsigned j = k / NB;
            bool is_upper_tri = (Arrange == cusolverdx::col_major) ? (i <= j) : (i >= j);
            if (is_upper_tri) {
