//////// Blocked Cholesky Implementation ////////

template<unsigned NB, cusolverdx::arrangement Arrange, class T>
__device__ T* tile(T* A, unsigned lda, unsigned i, unsigned j) {
    if (Arrange == cusolverdx::col_major) {
