    if (maxLength < length) {
        maxLength = length;
    }

    if ((outputFmt & 4) && (outputFmt & 2)) {
        printf("printing average and all samples doesn't make sense\n");
    }

    if (length == 0 || width == 0 || outputFmt == 0 || outputFmt > 5 || pattern > 1) {
        usage();
        return 0;
    }

    bool singleEntry = (pattern == 1);

