                (is_same<base_type, bf8_t>::value && is_same<additional_type, f8_t>::value),
            "base_type must be double, float, tf32_t, half, bfloat16, int8_t, f8_t or bf8_t!");

        static_for<0, KPack / mfma_instr.k_per_blk, 1>{}([&](auto k) {
