    if (rank == 0)
    {
        printf("Getting the device count and local extent ...\n");
    }
    // get the equation parts
    std::vector<std::vector<char>> eqs = split_equation(eq);
    assert(eqs.size() == 3);
    if (rank == 0)
    {
        printf("split_equation: %s\n", eq.c_str());
        printf("modeA: ");
        for (auto& m : eqs[0])
        {
            printf("%c ", m);
        }
        printf("\n");
        printf("modeB: ");
        for (auto& m : eqs[1])
        {
