        printf("\n");
        printf("localExtentB: ");
        for (auto& e : localExtentB)
        {
            printf("%ld ", e);
        }
        printf("\n");
        printf("localExtentC: ");
        for (auto& e : localExtentC)
        {
            printf("%ld ", e);
