__device__ void ActivationFunction_TanH_Diff(T (&__restrict__ bot_diff)[N],
                                                             const T (&__restrict__ top_diff)[N],
                                                             const T* /*bot_data*/,
                                                             const T (&__restrict__ top_data)[N],
                                                             const T /*diff_scale*/,
                                                             const T /*gamma*/,
                                                             const T beta,
                                                             const T alpha)
{
    for(uint i = 0; i < N; ++i)
    {
        // dy/dx = alpha * (beta - y^2 / beta)
        T y         = top_data[i];
        bot_diff[i] = fabs(beta) <= static_cast<T>(EPSILON)
                          ? static_cast<T>(0)
                          : (top_diff[i] * alpha * (beta - y * y / beta));
    }
}

